import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"UGSo HA Apps","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects-mqtt/index.md","filePath":"en/projects-mqtt/index.md","lastUpdated":1792850658000}'),i={name:"en/projects-mqtt/index.md"};function s(n,e,l,p,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ugso-ha-apps" tabindex="-1">UGSo HA Apps <a class="header-anchor" href="#ugso-ha-apps" aria-label="Permalink to &quot;UGSo HA Apps&quot;">​</a></h1><p>The shared repository is the central publishing location for all UGSo Software Home Assistant apps: MQTT apps, Grafik Visual Studio, Blocks for HA and future projects. Each app has its own subdirectory, version and documentation. The existing repository URL is retained.</p><h2 id="ugso-ha-apps-and-other-projects" tabindex="-1">UGSo HA Apps and other projects <a class="header-anchor" href="#ugso-ha-apps-and-other-projects" aria-label="Permalink to &quot;UGSo HA Apps and other projects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Project</th><th>Documentation</th></tr></thead><tbody><tr><td><a href="/en/projects/dashboard-user-manager/">Dashboard User Manager</a></td><td>0.1.4: user checkbox columns, bulk/individual assignments, automatic DE/EN/FR interface and dashboard backup before saving.</td></tr><tr><td><a href="/en/projects/callmebot/">CallMeBot Whatsapp</a></td><td>Experimental HA App 0.1.4: recipient profiles, WhatsApp texts via MQTT, DE/EN/FR and matching Blockly blocks.</td></tr><tr><td><a href="/en/projects/callmebot-signal/">CallMeBot Signal</a></td><td>Experimental HA app 0.1.0: Signal texts, phone/UUID profiles, separate MQTT namespace and Blockly profile selection in DE/EN/FR.</td></tr><tr><td><a href="/en/projects/blocks-for-ha/">Blocks for HA</a></td><td>Experimental HA app 0.1.3: visual Blocks for native automations, YAML import/export and extensible branches; editor through HA ingress.</td></tr><tr><td><a href="/en/projects/grafik-visual-studio/">Grafik Visual Studio</a></td><td>Graphical editor and runtime for HA visualizations.</td></tr></tbody></table><p>These projects live in the same repository as the MQTT apps below.</p><h2 id="shared-add-on-repository" tabindex="-1">Shared Add-on Repository <a class="header-anchor" href="#shared-add-on-repository" aria-label="Permalink to &quot;Shared Add-on Repository&quot;">​</a></h2><p>The MQTT projects are now primarily provided through a shared Home Assistant add-on repository. Home Assistant only needs one repository URL; after adding it, the individual projects appear separately in the add-on store.</p><p>Repository URL for Home Assistant:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Included add-ons:</p><ul><li><p>FRITZ!Box to MQTT</p></li><li><p>Heizöl to MQTT</p></li><li><p>Parcel to MQTT (development discontinued)</p></li><li><p><a href="/en/projects/mqtt-client/">MQTT-Client</a>: send selected Home Assistant devices and values to ioBroker or an external MQTT broker. <strong>0.1.16</strong> adds live state changes with polling fallback, detailed status, confirmed cleanup of recorded obsolete retained topics, additional commands, JSON settings backup and custom TLS certificates. Existing settings remain valid; retained data is never deleted automatically. The existing HA broker stays in place.</p></li><li><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons" target="_blank" rel="noreferrer">Open the shared add-on repository on GitHub</a></p></li></ul><p>The former single-project repositories remain visible as archived history and point to this shared repository.</p><h2 id="fritz-box-to-mqtt" tabindex="-1">FRITZ!Box to MQTT <a class="header-anchor" href="#fritz-box-to-mqtt" aria-label="Permalink to &quot;FRITZ!Box to MQTT&quot;">​</a></h2><p><strong>FRITZ!Box to MQTT</strong></p><p>A Home Assistant app that publishes FRITZ!Box data as MQTT Discovery entities. It combines TR-064, FRITZ!Box web/Lua queries and the live call monitor.</p><ul><li><a href="/en/projects/fritzbox-to-mqtt/">Open the FRITZ!Box to MQTT documentation</a></li><li><a href="https://github.com/rockbaer2007/fritzbox-to-mqtt" target="_blank" rel="noreferrer">Open the archived single-project repository on GitHub</a></li></ul><h2 id="heizol-to-mqtt" tabindex="-1">Heizöl to MQTT <a class="header-anchor" href="#heizol-to-mqtt" aria-label="Permalink to &quot;Heizöl to MQTT&quot;">​</a></h2><p><strong>Heizöl to MQTT</strong></p><p>A Home Assistant app that publishes heating-oil prices from Esyoil and Heizöl24 as MQTT Discovery entities. It currently publishes best prices and up to six provider offers per source and amount.</p><ul><li><a href="/en/projects/heizoel-to-mqtt/">Open the Heizöl to MQTT documentation</a></li><li><a href="https://github.com/rockbaer2007/heizoel-to-mqtt" target="_blank" rel="noreferrer">Open the archived single-project repository on GitHub</a></li><li>Adapted from: <a href="https://github.com/TA2k/ioBroker.heizoel" target="_blank" rel="noreferrer">TA2k/ioBroker.heizoel</a></li></ul><h2 id="parcel-to-mqtt" tabindex="-1">Parcel to MQTT <a class="header-anchor" href="#parcel-to-mqtt" aria-label="Permalink to &quot;Parcel to MQTT&quot;">​</a></h2><p><strong>Parcel to MQTT</strong></p><p><strong>Development discontinued:</strong> Parcel Tracker is already much further along, so we are discontinuing development of our package. We recommend taking a look at <a href="https://github.com/SoerenKaiser99/parcel_tracker" target="_blank" rel="noreferrer">Parcel Tracker by SoerenKaiser99</a>. Our existing documentation remains available as an archive.</p><p>A Home Assistant app that publishes parcel tracking data as MQTT Discovery entities. The current version uses DHL account parcel lists, optional DHL tracking numbers and Hermes parcel tracking.</p><ul><li><a href="/en/projects/parcel-to-mqtt/">Open the Parcel to MQTT documentation</a></li><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/parcel_to_mqtt" target="_blank" rel="noreferrer">Open the package in the shared add-on repository</a></li><li><a href="https://github.com/rockbaer2007/parcel-to-mqtt" target="_blank" rel="noreferrer">Open the archived single-project repository on GitHub</a></li><li>Adapted from: <a href="https://github.com/TA2k/ioBroker.parcel" target="_blank" rel="noreferrer">TA2k/ioBroker.parcel</a></li></ul><h2 id="more-project-areas" tabindex="-1">More Project Areas <a class="header-anchor" href="#more-project-areas" aria-label="Permalink to &quot;More Project Areas&quot;">​</a></h2><ul><li><a href="/en/projects/">Open C# Projects</a></li><li><a href="/en/projects-diverse/">Open Misc Projects</a></li><li><a href="/en/projects/atlas/">Open ATLAS</a></li></ul>',27)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
